select
  RowID, StudyID, SFXMDM, XXDM, CheckDate, CheckTime, ItemResult, ItemUnit, SampleNO, Flag, DefValue, Doctor, OrderCode, SendFlag, SHDoctor, CheckMethod, CheckStuff, BZ, DeptCode
from hyb

    
        and RowID = #{rowid}
    
    
        and StudyID = #{studyid}
    
    
        and SFXMDM = #{sfxmdm}
    
    
        and XXDM = #{xxdm}
    
    
        and CheckDate = #{checkdate}
    
    
        and CheckTime = #{checktime}
    
    
        and ItemResult = #{itemresult}
    
    
        and ItemUnit = #{itemunit}
    
    
        and SampleNO = #{sampleno}
    
    
        and Flag = #{flag}
    
    
        and DefValue = #{defvalue}
    
    
        and Doctor = #{doctor}
    
    
        and OrderCode = #{ordercode}
    
    
        and SendFlag = #{sendflag}
    
    
        and SHDoctor = #{shdoctor}
    
    
        and CheckMethod = #{checkmethod}
    
    
        and CheckStuff = #{checkstuff}
    
    
        and BZ = #{bz}
    
    
        and DeptCode = #{deptcode}
    

limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from hyb

    
        and RowID = #{rowid}
    
    
        and StudyID = #{studyid}
    
    
        and SFXMDM = #{sfxmdm}
    
    
        and XXDM = #{xxdm}
    
    
        and CheckDate = #{checkdate}
    
    
        and CheckTime = #{checktime}
    
    
        and ItemResult = #{itemresult}
    
    
        and ItemUnit = #{itemunit}
    
    
        and SampleNO = #{sampleno}
    
    
        and Flag = #{flag}
    
    
        and DefValue = #{defvalue}
    
    
        and Doctor = #{doctor}
    
    
        and OrderCode = #{ordercode}
    
    
        and SendFlag = #{sendflag}
    
    
        and SHDoctor = #{shdoctor}
    
    
        and CheckMethod = #{checkmethod}
    
    
        and CheckStuff = #{checkstuff}
    
    
        and BZ = #{bz}
    
    
        and DeptCode = #{deptcode}

select count(1)
from hyb

    
        and CheckDate = #{params.recordingDate}

select
RowID, StudyID, SFXMDM, XXDM, CheckDate, CheckTime, ItemResult, ItemUnit, SampleNO, Flag, DefValue, Doctor, OrderCode, SendFlag, SHDoctor, CheckMethod, CheckStuff, BZ, DeptCode
from hyb

    
        and CheckDate = #{hyb.params.recordingDate}
    

order by StudyID
limit #{pageable.offset}, #{pageable.pageSize}
